class Solution:
    def findDuplicates(self, nums: list[int]) -> list[int]:
        res = []
        for x in nums:                     # one pass, O(n)
            i = abs(x) - 1                 # value v is recorded at index v - 1; x may already be negated
            if nums[i] < 0:                # sign already flipped => v was seen before
                res.append(abs(x))
            else:
                nums[i] = -nums[i]         # mark v as seen using the spare sign bit
        return res
